// One item out: this week's ranked top slice for the keyword.
// The Sort node upstream has already put the most-saved pin first.
const cfg = $('Keyword and thresholds').first().json;
const topN = Math.max(1, Number(cfg.topN) || 25);

const pins = $input.all()
  .map((i) => i.json)
  .filter((p) => p && p.id && p.title)
  .slice(0, topN)
  .map((p, idx) => ({
    id: String(p.id),
    rank: idx + 1,
    title: p.title,
    saves: Number(p.repinCount) || 0,
    url: p.pinUrl || null,
  }));

if (!pins.length) {
  throw new Error('Pinterest returned no usable pins for "' + cfg.query + '". Stopping here rather than writing an empty week into the history and calling it a drop.');
}

return [{
  json: {
    keyword: cfg.query,
    capturedAt: new Date().toISOString().slice(0, 10),
    pins,
    snapshot: JSON.stringify(pins),
  },
}];

// Compare this week's top slice with the most recent earlier snapshot for the
// same keyword. A first run has nothing to compare against and says so instead
// of reporting every pin as new.
const cfg = $('Keyword and thresholds').first().json;
const now = $('Keep the top slice').first().json;
const minMove = Math.max(1, Number(cfg.minRankMove) || 3);

const parseSnapshot = (s) => {
  try {
    const v = JSON.parse(s);
    return Array.isArray(v) ? v.filter((p) => p && p.id) : [];
  } catch (e) {
    return [];
  }
};

const base = {
  keyword: now.keyword,
  week: now.capturedAt,
  snapshot: now.snapshot,
  topPin: now.pins[0].title,
  topSaves: now.pins[0].saves,
  pinsTracked: now.pins.length,
};

// Earlier weeks only. Rows the sheet has not filled in are ignored, not guessed at.
const history = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.Snapshot && r.Week && String(r.Week) < now.capturedAt)
  .sort((a, b) => String(b.Week).localeCompare(String(a.Week)));

const previous = history.find((r) => parseSnapshot(r.Snapshot).length > 0);

if (!previous) {
  return [{
    json: Object.assign({}, base, {
      firstRun: true,
      changed: false,
      comparedWith: null,
      entered: [],
      left: [],
      moved: [],
      report: 'No earlier snapshot for "' + now.keyword + '". This run stores the baseline; next week has something to compare against.',
    }),
  }];
}

const before = new Map(parseSnapshot(previous.Snapshot).map((p) => [String(p.id), p]));
const current = new Map(now.pins.map((p) => [p.id, p]));

const entered = now.pins
  .filter((p) => !before.has(p.id))
  .map((p) => ({ title: p.title, rank: p.rank, saves: p.saves, url: p.url }));

const left = [...before.values()]
  .filter((p) => !current.has(String(p.id)))
  .map((p) => ({ title: p.title || '(title not stored)', rank: p.rank }))
  .sort((a, b) => a.rank - b.rank);

const moved = now.pins
  .filter((p) => before.has(p.id))
  .map((p) => {
    const was = before.get(p.id);
    return {
      title: p.title,
      from: was.rank,
      to: p.rank,
      places: was.rank - p.rank,
      savesGained: p.saves - (Number(was.saves) || 0),
    };
  })
  .filter((m) => Math.abs(m.places) >= minMove)
  .sort((a, b) => Math.abs(b.places) - Math.abs(a.places));

const fmt = (n) => (n >= 0 ? '+' + n : String(n));
const lines = [
  'Keyword: ' + now.keyword,
  'This week: ' + now.capturedAt + '   Previous: ' + previous.Week,
  'Top slice size: ' + now.pins.length,
  '',
  'New in the top slice:',
  ...(entered.length ? entered.map((e) => '- #' + e.rank + ' ' + e.title + ' (' + e.saves + ' saves)') : ['- none']),
  '',
  'Dropped out of the top slice:',
  ...(left.length ? left.map((l) => '- was #' + l.rank + ' ' + l.title) : ['- none']),
  '',
  'Moved ' + minMove + ' places or more:',
  ...(moved.length ? moved.map((m) => '- ' + m.title + ': #' + m.from + ' to #' + m.to + ' (' + fmt(m.savesGained) + ' saves)') : ['- none']),
];

return [{
  json: Object.assign({}, base, {
    firstRun: false,
    changed: entered.length > 0 || left.length > 0 || moved.length > 0,
    comparedWith: previous.Week,
    entered,
    left,
    moved,
    report: lines.join('\n'),
  }),
}];

